140	    public boolean isIncluded(String url) {
141	        if (url == null) {
142	            return false;
143	        }
144	        if (url.indexOf("?") > 0) {
145	            // Strip off any parameters
146	            url = url.substring(0, url.indexOf("?"));
147	        }
148	        for (Pattern p : this.includeInPatterns) {
149	            if (p.matcher(url).matches()) {
150	                return true;
151	            }
152	        }
153	        return false;
154	    }
