299	    private void fillNodesInContext(SiteNode rootNode, List<SiteNode> nodesList) {
300	        @SuppressWarnings("unchecked")
301	        Enumeration<TreeNode> en = rootNode.children();
302	        while (en.hasMoreElements()) {
303	            SiteNode sn = (SiteNode) en.nextElement();
304	            if (isInContext(sn)) {
305	                nodesList.add(sn);
306	            }
307	            fillNodesInContext(sn, nodesList);
308	        }
309	    }
