492	            SiteNode parent, String nodeName, HistoryReference baseRef, HttpMessage baseMsg)
493	            throws URIException,
494	                    HttpMalformedHeaderException,
495	                    NullPointerException,
496	                    DatabaseException {
497	        LOGGER.debug("findAndAddChild {} / {}", parent.getNodeName(), nodeName);
498	        if (isReferenceCached(baseRef)) {
499	            return hrefMap.get(baseRef.getHistoryId());
500	        }
501	        SiteNode result = findChild(parent, nodeName);
502	        if (result == null) {
503	            SiteNode newNode = null;
504	            if (!baseRef.getCustomIcons().isEmpty()) {
505	                newNode = new SiteNode(this, baseRef.getHistoryType(), nodeName);
506	                newNode.setCustomIcons(baseRef.getCustomIcons(), baseRef.getClearIfManual());
507	            } else {
508	                newNode = new SiteNode(this, baseRef.getHistoryType(), nodeName);
509	            }
510	
511	            int pos = parent.getChildCount();
512	            for (int i = 0; i < parent.getChildCount(); i++) {
513	                if (((SiteNode) parent.getChildAt(i)).isParentOf(nodeName)) {
514	                    pos = i;
515	                    break;
516	                }
517	            }
518	
519	            result = newNode;
520	            result.setHistoryReference(
521	                    createReference(createTreeNodePath(parent, newNode), baseRef, baseMsg));
